package com.dukankhata.pos.dto;
import com.dukankhata.pos.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public record SaleResponse(UUID id,String invoiceNumber,BigDecimal subtotal,BigDecimal taxableAmount,BigDecimal tax,BigDecimal cgstAmount,BigDecimal sgstAmount,BigDecimal igstAmount,BigDecimal total,String status,Instant createdAt,UUID customerId,String customerName,String customerMobile,UUID sellerId,BigDecimal sellerCommissionRate,BigDecimal sellerCommissionAmount,List<Item> items,List<Payment> payments){
 public record Item(String name,BigDecimal unitPrice,BigDecimal quantity,BigDecimal lineTotal,String hsnCode,BigDecimal gstRate,BigDecimal taxableAmount,BigDecimal cgstAmount,BigDecimal sgstAmount,BigDecimal igstAmount){} public record Payment(String method,BigDecimal amount){}
 public static SaleResponse from(Sale s){return new SaleResponse(s.getId(),s.getInvoiceNumber(),s.getSubtotal(),s.getTaxableAmount(),s.getTax(),s.getCgstAmount(),s.getSgstAmount(),s.getIgstAmount(),s.getTotal(),s.getStatus().name(),s.getCreatedAt(),s.getCustomer()==null?null:s.getCustomer().getId(),s.getCustomer()==null?null:s.getCustomer().getName(),s.getCustomer()==null?null:s.getCustomer().getMobile(),s.getSeller()==null?null:s.getSeller().getId(),s.getSellerCommissionRate(),s.getSellerCommissionAmount(),s.getItems().stream().map(i->new Item(i.getItemName(),i.getUnitPrice(),i.getQuantity(),i.getLineTotal(),i.getHsnCode(),i.getGstRate(),i.getTaxableAmount(),i.getCgstAmount(),i.getSgstAmount(),i.getIgstAmount())).toList(),s.getPayments().stream().map(p->new Payment(p.getMethod().name(),p.getAmount())).toList());}
}
